/**
 * issue #39 (Proposal A): a thin delegating/mirroring Node-RED
 * `storageModule` adapter that lets an ORDINARY, already-running Node-RED
 * editor instance ("A") keep using its own storage backend for everything,
 * while its normal Deploy button ALSO ships the deployed flow + current
 * encrypted credential bundle to a separate node-red-temporal execution
 * runner ("B") - see the issue for the full accepted design/decision
 * record. This module implements ONLY the storage-wrapper seam; it never
 * touches the Node-RED editor, never adds a custom flow format, and never
 * builds a custom deploy endpoint (Proposal C is documented as a fallback
 * only - not needed here, see README).
 *
 * Node-RED's storage facade (`@node-red/runtime/lib/storage/index.js`)
 * calls a user-supplied `storageModule`'s `saveFlows(flows, user)` with the
 * flow array ONLY - credentials are persisted separately via a prior
 * `saveCredentials(credentials)` call, and only when Node-RED considers
 * them dirty for this deploy. That's why a newly (re)provisioned runner B
 * still needs a REAL current credential bundle on every remote deploy: this
 * adapter always re-reads `delegate.getCredentials()` after the local save
 * completes, rather than relying on `saveCredentials` having just run.
 *
 * v1 decisions baked in here (see issue #39 for the full rationale):
 *   - `saveCredentials()` is delegated UNCHANGED - never touched/logged.
 *   - `saveFlows()` delegates locally FIRST, then remote-deploys; if the
 *     remote deploy fails, `saveFlows()` REJECTS so Node-RED's own Deploy
 *     request surfaces a real error (local save may already have
 *     succeeded - documented as acceptable in the issue).
 *   - remote deploys are always `Node-RED-Deployment-Type: full`.
 *   - A's local revision is never forwarded as B's `rev` - the request body
 *     omits `rev` entirely so B's `runtime.flows.setFlows()` generates its
 *     own revision (never conflate the two instances' revisions).
 *   - authentication reuses B's existing Node-RED Admin API surface: an
 *     optional bearer token is forwarded via `Authorization`, no custom
 *     auth subsystem.
 *   - credential contents are NEVER logged, decoded, or inspected - they
 *     are forwarded byte-for-byte from `delegate.getCredentials()` straight
 *     into the request body.
 */

"use strict";

const DEFAULT_ADMIN_API_VERSION = "v2";
const DEFAULT_DEPLOYMENT_TYPE = "full";

/**
 * @param {object} delegate - the user's existing (real) Node-RED
 *   `storageModule` (e.g. the built-in `localfilesystem` module, or any
 *   custom storage backend already in use). ALL of its methods are
 *   preserved unchanged except `saveFlows`.
 * @param {object} options
 * @param {string} options.target - base URL of the remote node-red-temporal
 *   runner's Admin API, e.g. "http://localhost:1881" or
 *   "https://runner.example.com".
 * @param {string} [options.token] - optional bearer token forwarded as
 *   `Authorization: Bearer <token>`, reusing the runner's own Node-RED
 *   Admin API authentication (no custom auth subsystem).
 * @param {function} [options.fetch] - injectable `fetch` implementation,
 *   for tests. Defaults to the global `fetch` (Node >=18).
 * @returns {object} a Node-RED-compatible `storageModule`
 */
function createRemoteDeployStorage(delegate, options) {
    if (!delegate || typeof delegate.saveFlows !== "function" || typeof delegate.getCredentials !== "function") {
        throw new Error("remoteDeployStorage requires a delegate storageModule implementing saveFlows()/getCredentials()");
    }
    options = options || {};
    if (!options.target) {
        throw new Error("remoteDeployStorage requires options.target (the remote node-red-temporal runner's base URL)");
    }

    const target = String(options.target).replace(/\/+$/, "");
    const token = options.token;
    const fetchImpl = options.fetch || (typeof fetch === "function" ? fetch : undefined);
    if (typeof fetchImpl !== "function") {
        throw new Error("remoteDeployStorage requires a global fetch implementation (Node >=18) or an injected options.fetch");
    }

    /**
     * Full-only v2 deployment to the remote runner. Never logs the
     * credentials payload - only non-sensitive metadata (target, status)
     * may ever reach a log line.
     * @param {Array<object>} flows
     * @param {object} credentials - opaque encrypted credential bundle as
     *   returned by `delegate.getCredentials()`; never inspected here.
     */
    async function deployToRemote(flows, credentials) {
        const headers = {
            "Content-Type": "application/json",
            "Node-RED-API-Version": DEFAULT_ADMIN_API_VERSION,
            "Node-RED-Deployment-Type": DEFAULT_DEPLOYMENT_TYPE
        };
        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }

        let response;
        try {
            // Intentionally no `rev`: A's revision must never be forwarded
            // as B's optimistic-lock revision (issue #39 decision #4).
            response = await fetchImpl(`${target}/flows`, {
                method: "POST",
                headers,
                body: JSON.stringify({ flows, credentials })
            });
        } catch (err) {
            throw new Error(`remote deploy to ${target} failed: ${err && err.message ? err.message : err}`);
        }

        if (!response.ok) {
            let detail = "";
            try {
                detail = await response.text();
            } catch (readErr) {
                // ignore: body may already be consumed/unavailable
            }
            throw new Error(`remote deploy to ${target} failed with status ${response.status}${detail ? `: ${detail}` : ""}`);
        }
    }

    // Preserve every other delegate method (getFlows, saveCredentials,
    // getSettings/saveSettings, getSessions/saveSessions, library entries,
    // projects, sshkeys, init, ...) completely unchanged - only `saveFlows`
    // is overridden. Using Object.assign (not a Proxy) keeps this a plain,
    // inspectable object matching what `@node-red/runtime/lib/storage/
    // index.js`'s `moduleSelector()` expects.
    return Object.assign({}, delegate, {
        /**
         * @param {Array<object>} flows
         * @param {object} [user]
         * @returns {Promise<void>} rejects if the LOCAL save fails, OR if
         *   the remote deploy fails/errors (issue #39 decision #3) - a
         *   remote failure must surface as a normal Deploy error in
         *   Node-RED, even though the local save may already have
         *   succeeded.
         */
        async saveFlows(flows, user) {
            await delegate.saveFlows(flows, user);
            const credentials = await delegate.getCredentials();
            await deployToRemote(flows, credentials);
        }
    });
}

module.exports = { createRemoteDeployStorage };
